export interface TempDatabaseOptions {
  readonly initialize?: (service: SqliteService) => void;
}

export interface TempDatabase {
  readonly service: SqliteService;
  readonly dispose: () => void;
}

export interface CleanupBatch {
  readonly add: (dispose: () => void, step: string) => void;
  readonly disposeAll: () => ReadonlyArray<CleanupFailure>;
}

export const makeCleanupBatch = (): CleanupBatch => { ... };

export const makeTempDatabase = (
  batch: CleanupBatch,
  options: TempDatabaseOptions = {},
): TempDatabase => {
  const dir = mkdtempSync(join(tmpdir(), "s268-sql-owner-"));
  batch.add(() => rmSync(dir, {force: true, recursive: true}), "remove-directory");
  let service: SqliteService | undefined;
  let ownsService = false;
  try {
    service = makeSync({ databasePath: join(dir, "owner.sqlite") });
    ownsService = true;
    (options.initialize ?? createTable)(service);
    const owned = service;
    let disposed = false;
    const dispose = () => {
      if (disposed) return;
      disposed = true;
      owned.closeSync();
      rmSync(dir, { force: true, recursive: true });
    };
    batch.add(dispose, "dispose-service");
    return { service: owned, dispose };
  } catch (error) {
    if (service !== undefined) {
      try { service.closeSync(); } catch (closeError) { report? }
    }
    try { rmSync(dir, ...); } catch (removeError) { report? }
    throw error;
  }
};
```

